{
  "id": "V066",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "고객 의견의 반복 요구와 불편 주제를 파악하려는 목적이 보존됩니다."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "주제별 경향을 파악·분석하고 의견을 요약하는 작업이 보존됩니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "이번 주 고객 의견과 그 안의 요구·불편 주제가 포함됩니다."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "이번 주 접수된 고객 의견이 입력으로 보존됩니다."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "경향을 뒷받침하는 의견을 포함한 회의용 요약 자료가 명시됩니다."
    },
    {
      "field": "constraints",
      "score": 0,
      "reason": "개별 고객 답장과 제품 개선 효과 예측 제외 조건이 모든 뷰에서 빠졌습니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능을 추가한 표현은 없습니다."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "역할 구분이 핵심 요구에 명시되지 않았으며 뷰도 새로운 역할을 부여하지 않습니다."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "개별 고객에게 답장을 보내거나 제품 개선의 효과를 예측하는 작업은 제외합니다.",
      "view_quote": "",
      "reason": "답장과 효과 예측을 제외한다는 제약이 모든 뷰에서 누락됐습니다."
    }
  ],
  "permission_interpretation": "답장 및 효과 예측은 제외 대상이며, 뷰는 AI가 이를 수행한다고 주장하지 않습니다."
}
